(6104323, 898555, 109478, '<td valign="top">a little blur</td>', 'a little blur', '2010-07-26 08:31:19.000000', NULL, 1),
(6104337, 899628, 67258, '<td valign="top">I can only tell that this is taken utilising a shallow depth of field  from the hint of a third leaf to the rear left.  For this challenge, I feel that you would have been better choosing a background which would have allowed for some bokeh to act as a foil to the rose.  As it is, it gives the apearance of a studio shot with a solid background - fine, but not, perhaps, ideal for this challenge.</td>', 'I can only tell that this is taken utilising a shallow depth of field  from the hint of a third leaf to the rear left.  For this challenge, I feel that you would have been better choosing a background which would have allowed for some bokeh to act as a foil to the rose.  As it is, it gives the apearance of a studio shot with a solid background - fine, but not, perhaps, ideal for this challenge.', '2010-07-26 09:09:16.000000', NULL, 1),
(6104341, 898947, 65234, '<td valign="top">Pretty, creamy bokeh!  Dreamy image.</td>', 'Pretty, creamy bokeh!  Dreamy image.', '2010-07-26 09:22:58.000000', NULL, 1),
(6104343, 898540, 62357, '<td valign="top">Excellent.  Wonderful colours.  Like it very much.</td>', 'Excellent.  Wonderful colours.  Like it very much.', '2010-07-26 09:23:55.000000', NULL, 1),
(6104344, 899315, 65234, '<td valign="top">Certainly shallow DOF; would like the butterfly''s eye to be a bit sharper.</td>', 'Certainly shallow DOF; would like the butterfly''s eye to be a bit sharper.', '2010-07-26 09:24:11.000000', NULL, 1),
(6104346, 899471, 65234, '<td valign="top">Sharp where it should be.</td>', 'Sharp where it should be.', '2010-07-26 09:24:36.000000', NULL, 1),
(6104347, 899613, 65234, '<td valign="top">Aww, a hug from a flower :-)  Fun image!</td>', 'Aww, a hug from a flower :-)  Fun image!', '2010-07-26 09:25:10.000000', NULL, 1),
(6104348, 899430, 65234, '<td valign="top">Sweet eye contact!  Background looks a little noisy and washed out to me.</td>', 'Sweet eye contact!  Background looks a little noisy and washed out to me.', '2010-07-26 09:27:02.000000', NULL, 1),
(6104351, 899630, 65234, '<td valign="top">Egads; you''re brave!  I try not to take macro shots of nasty stinging things (bees are OK; hornets and wasps, not so much).  You got nice detail here.</td>', 'Egads; you''re brave!  I try not to take macro shots of nasty stinging things (bees are OK; hornets and wasps, not so much).  You got nice detail here.', '2010-07-26 09:29:11.000000', NULL, 1),
(6104352, 898540, 119419, '<td valign="top">I like this for the feel and the colour</td>', 'I like this for the feel and the colour', '2010-07-26 09:29:28.000000', NULL, 1),
(6104353, 899343, 65234, '<td valign="top">Interesting!  Feels like the end of a summer day at the beach.</td>', 'Interesting!  Feels like the end of a summer day at the beach.', '2010-07-26 09:30:17.000000', NULL, 1),
(6104354, 899342, 119419, '<td valign="top">nice concept, perhaps a little to busy in the back</td>', 'nice concept, perhaps a little to busy in the back', '2010-07-26 09:31:19.000000', NULL, 1),
