(6104366, 899200, 65234, '<td valign="top">Like the light and pattern.  I might angle the composition a bit, I think.</td>', 'Like the light and pattern.  I might angle the composition a bit, I think.', '2010-07-26 09:37:04.000000', NULL, 1),
(6104368, 898912, 65234, '<td valign="top">For some reason this reminds me of the animated Pixar desk lamps ;-)</td>', 'For some reason this reminds me of the animated Pixar desk lamps ;-)', '2010-07-26 09:37:55.000000', NULL, 1),
(6104370, 899611, 119419, '<td valign="top">now that''s shallow :)</td>', 'now that''s shallow :)', '2010-07-26 09:38:49.000000', NULL, 1),
(6104373, 899527, 65234, '<td valign="top">Nice detail and I like the soothing green of the background.  The abdomen being a foreground OOF element bothers me a little; I think it would work better if the perspective were such that the abdomen was fading into ther background.  Assuming you could direct your subject ;-)</td>', 'Nice detail and I like the soothing green of the background.  The abdomen being a foreground OOF element bothers me a little; I think it would work better if the perspective were such that the abdomen was fading into ther background.  Assuming you could direct your subject ;-)', '2010-07-26 09:43:44.000000', NULL, 1),
(6104374, 899577, 65234, '<td valign="top">Looks like a teensy little fly!</td>', 'Looks like a teensy little fly!', '2010-07-26 09:44:22.000000', NULL, 1),
(6104375, 899264, 46918, '<td valign="top">I love the shot...Being an ex soldier myself this means alot to me....The focus is perfect. His foot is cut off but that is ok.</td>', 'I love the shot...Being an ex soldier myself this means alot to me....The focus is perfect. His foot is cut off but that is ok.', '2010-07-26 09:44:23.000000', NULL, 1),
(6104376, 898886, 65234, '<td valign="top">Interesting.  Effective use of shallow DOF to tell a story.</td>', 'Interesting.  Effective use of shallow DOF to tell a story.', '2010-07-26 09:45:08.000000', NULL, 1),
