(6104478, 899468, 115644, '<td valign="top">best of the sunflowers IMO (so far)</td>', 'best of the sunflowers IMO (so far)', '2010-07-26 11:07:31.000000', NULL, 1),
(6104480, 899376, 119485, '<td valign="top">I love the colors</td>', 'I love the colors', '2010-07-26 11:12:07.000000', NULL, 1),
