(6104516, 899343, 86447, '<td valign="top">Lovely tones... and I like the grains of sand... the feet make me sad.</td>', 'Lovely tones... and I like the grains of sand... the feet make me sad.', '2010-07-26 11:55:52.000000', NULL, 1),
(6104523, 899629, 117285, '<td valign="top">In order for DOF to half impact you need some background to emphasize the separation.  It''s a nice shot and the foreground is soft but that where the impact stops because the framing is too tight on the subject.</td>', 'In order for DOF to half impact you need some background to emphasize the separation.  It''s a nice shot and the foreground is soft but that where the impact stops because the framing is too tight on the subject.', '2010-07-26 12:06:50.000000', NULL, 1),
(6104524, 899220, 117285, '<td valign="top">I''d say there is too little depth of field in this shot.  Because they are too small in the frame I don''t find the fly''s eyes that interesting to be the only point emphasized by focus. 5</td>', 'I''d say there is too little depth of field in this shot.  Because they are too small in the frame I don''t find the fly''s eyes that interesting to be the only point emphasized by focus. 5', '2010-07-26 12:11:04.000000', NULL, 1),
