INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6108128, 899130, 117831, '<td valign="top">lovely lighting - great detail - and very crisp! great job!! (7)</td>', 'lovely lighting - great detail - and very crisp! great job!! (7)', '2010-07-28 22:24:09.000000', NULL, 1),
(6108129, 898340, 65234, '<td valign="top">LOL at your title ;-)  Not exactly a pretty scene, but well captured.</td>', 'LOL at your title ;-)  Not exactly a pretty scene, but well captured.', '2010-07-28 22:24:47.000000', NULL, 1),
(6108230, 899609, 42495, '<td valign="top">Your DOF is certainly shallow here and it works for meeting the challenge theme.  I think the composition would work better if the flower were emanating from the lower right corner, creating a diagonal.  The lighting here is hard, but you can always use some type of light modifier to soften it, it makes a huge difference.  They can be handmade and you don''t need an expensive diffuser to soften the light.  It looks like the brighter part of the flower is blown out; it would be nice to see detail there.   Again, a light modifier would take care of that.</td>', 'Your DOF is certainly shallow here and it works for meeting the challenge theme.  I think the composition would work better if the flower were emanating from the lower right corner, creating a diagonal.  The lighting here is hard, but you can always use some type of light modifier to soften it, it makes a huge difference.  They can be handmade and you don''t need an expensive diffuser to soften the light.  It looks like the brighter part of the flower is blown out; it would be nice to see detail there.   Again, a light modifier would take care of that.', '2010-07-29 00:46:09.000000', NULL, 1),
(6108254, 899454, 117534, '<td valign="top">You nailed the Challenge with this shot! Even though this isn''t the type of picture that I''d normaly stop and stare at, it totaly captivates me! I''ve been back looking at this and raising my score each time! This time a 9.. I may be back with a 10</td>', 'You nailed the Challenge with this shot! Even though this isn''t the type of picture that I''d normaly stop and stare at, it totaly captivates me! I''ve been back looking at this and raising my score each time! This time a 9.. I may be back with a 10', '2010-07-29 01:32:10.000000', NULL, 1),
(6108255, 899330, 117534, '<td valign="top">Nice</td>', 'Nice', '2010-07-29 01:33:29.000000', NULL, 1),
(6108257, 899644, 117534, '<td valign="top">Water droplet reflection?? Seriously Awesome!</td>', 'Water droplet reflection?? Seriously Awesome!', '2010-07-29 01:36:47.000000', NULL, 1),
