INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6112035, 899470, 98339, '<td valign="top">this is stunning in the color and tones...very, very well done</td>', 'this is stunning in the color and tones...very, very well done', '2010-08-01 17:37:13.000000', NULL, 1),
(6112086, 899493, 51747, '<td valign="top">Good DOF and a pretty image as well.</td>', 'Good DOF and a pretty image as well.', '2010-08-01 18:01:40.000000', NULL, 1),
(6112092, 899460, 51747, '<td valign="top">Fits the challenge well.</td>', 'Fits the challenge well.', '2010-08-01 18:03:28.000000', NULL, 1),
(6112100, 898962, 51747, '<td valign="top">This is a very colorful and dynamic image. I think it would present better if the insect was not looking at a nearby border but instead, looking into the image center.</td>', 'This is a very colorful and dynamic image. I think it would present better if the insect was not looking at a nearby border but instead, looking into the image center.', '2010-08-01 18:12:22.000000', NULL, 1),
(6112105, 899381, 51747, '<td valign="top">Very nice detail in the part of the image that''s in focus.</td>', 'Very nice detail in the part of the image that''s in focus.', '2010-08-01 18:14:20.000000', NULL, 1),
(6112112, 899402, 51747, '<td valign="top">Nice presentation. Nice sharp details.</td>', 'Nice presentation. Nice sharp details.', '2010-08-01 18:19:14.000000', NULL, 1),
(6112116, 899317, 51747, '<td valign="top">Nice sharp image. Good lines.</td>', 'Nice sharp image. Good lines.', '2010-08-01 18:20:40.000000', NULL, 1),
(6112118, 899426, 51747, '<td valign="top">Although you have isolated your subject from the background, the plant is not in sharp focus as it should be. 4</td>', 'Although you have isolated your subject from the background, the plant is not in sharp focus as it should be. 4', '2010-08-01 18:22:19.000000', NULL, 1),
(6112119, 898943, 51747, '<td valign="top">Perfect for the challenge.</td>', 'Perfect for the challenge.', '2010-08-01 18:22:48.000000', NULL, 1),
(6112123, 899264, 51747, '<td valign="top">I like the tones. Gives it an ''old'' feel. Not loving the composition.</td>', 'I like the tones. Gives it an ''old'' feel. Not loving the composition.', '2010-08-01 18:23:38.000000', NULL, 1),
(6112126, 898549, 51747, '<td valign="top">Good use of shallow DOF. I think the choice of red petals without the yellow tips would work better here as the extra yellow in the image takes away from the rings.</td>', 'Good use of shallow DOF. I think the choice of red petals without the yellow tips would work better here as the extra yellow in the image takes away from the rings.', '2010-08-01 18:25:17.000000', NULL, 1),
(6112127, 898498, 51747, '<td valign="top">Meets the challenge, emotive (with the title), but no pop.</td>', 'Meets the challenge, emotive (with the title), but no pop.', '2010-08-01 18:26:21.000000', NULL, 1),
(6112128, 899304, 51747, '<td valign="top">Nice shot for the challenge. The Bokeh in the background is perfect!</td>', 'Nice shot for the challenge. The Bokeh in the background is perfect!', '2010-08-01 18:27:08.000000', NULL, 1),
(6112130, 899528, 51747, '<td valign="top">Toy frog... but the lighting makes this shot very good.</td>', 'Toy frog... but the lighting makes this shot very good.', '2010-08-01 18:28:12.000000', NULL, 1),
(6112131, 899443, 51747, '<td valign="top">Nice sharp details on the Damselfly. A little less stick might help this have more impact.</td>', 'Nice sharp details on the Damselfly. A little less stick might help this have more impact.', '2010-08-01 18:29:33.000000', NULL, 1),
(6112135, 899005, 51747, '<td valign="top">Cool!</td>', 'Cool!', '2010-08-01 18:34:54.000000', NULL, 1),
(6112142, 899143, 51747, '<td valign="top">Effective lighting. Emotive. Good B&amp;W. Border is a plus.</td>', 'Effective lighting. Emotive. Good B&W. Border is a plus.', '2010-08-01 18:39:01.000000', NULL, 1),
(6112145, 899506, 51747, '<td valign="top">Very unusual for this challenge. I like your decision to use selective desat to emphasize the fingertips.</td>', 'Very unusual for this challenge. I like your decision to use selective desat to emphasize the fingertips.', '2010-08-01 18:42:50.000000', NULL, 1),
(6112147, 899468, 51747, '<td valign="top">Good choice of subject for this challenge. Something about the reds in the flowers bothers me a little. To a lesser extent, the horizon seems a little tilted. I feel this had potential to be better.</td>', 'Good choice of subject for this challenge. Something about the reds in the flowers bothers me a little. To a lesser extent, the horizon seems a little tilted. I feel this had potential to be better.', '2010-08-01 18:48:30.000000', NULL, 1),
(6112153, 898663, 51747, '<td valign="top">Nice piece of art. The colors work well together.</td>', 'Nice piece of art. The colors work well together.', '2010-08-01 18:58:45.000000', NULL, 1),
(6112164, 899297, 51747, '<td valign="top">Well done.</td>', 'Well done.', '2010-08-01 19:12:50.000000', NULL, 1),
(6112171, 898911, 51747, '<td valign="top">Pretty powerful image. Could be better if the eyes/head of the insect were sharper. Nice job.</td>', 'Pretty powerful image. Could be better if the eyes/head of the insect were sharper. Nice job.', '2010-08-01 19:17:43.000000', NULL, 1),
