(6112182, 899615, 51747, '<td valign="top">That''s an awesome looking bird. Nice capture.</td>', 'That''s an awesome looking bird. Nice capture.', '2010-08-01 19:29:59.000000', NULL, 1),
(6112280, 899636, 38930, '<td valign="top">Nice find!</td>', 'Nice find!', '2010-08-01 20:38:17.000000', NULL, 1),
