(6112283, 898947, 38930, '<td valign="top">I like the simplicity</td>', 'I like the simplicity', '2010-08-01 20:38:34.000000', NULL, 1),
(6112284, 899211, 38930, '<td valign="top">Awesome subject and great depth of field</td>', 'Awesome subject and great depth of field', '2010-08-01 20:38:50.000000', NULL, 1),
(6112286, 899474, 38930, '<td valign="top">Not a bad idea!  A suggestion for next time would be to make the raisins fill up more of the picture so there isn''t as much white space</td>', 'Not a bad idea!  A suggestion for next time would be to make the raisins fill up more of the picture so there isn''t as much white space', '2010-08-01 20:39:37.000000', NULL, 1),
(6112287, 899654, 38930, '<td valign="top">This would have looked great in color!</td>', 'This would have looked great in color!', '2010-08-01 20:39:52.000000', NULL, 1),
(6112289, 899003, 38930, '<td valign="top">Great colors!</td>', 'Great colors!', '2010-08-01 20:40:02.000000', NULL, 1),
(6112290, 899620, 38930, '<td valign="top">It works!  Nice depth of field.</td>', 'It works!  Nice depth of field.', '2010-08-01 20:40:14.000000', NULL, 1),
