(6112299, 898832, 38930, '<td valign="top">Awesome idea and shot!  Next time, shine a reflector on those flowers and it will really make them stand out :)</td>', 'Awesome idea and shot!  Next time, shine a reflector on those flowers and it will really make them stand out :)', '2010-08-01 20:42:23.000000', NULL, 1),
(6112301, 899431, 38930, '<td valign="top">Nice!  I like that you did this on an overcast day - it fits the lighthouse perfectly.</td>', 'Nice!  I like that you did this on an overcast day - it fits the lighthouse perfectly.', '2010-08-01 20:42:48.000000', NULL, 1),
(6112303, 899507, 38930, '<td valign="top">Good shot!  Maybe next time get in a little closer so she takes up more of the picture and there isn''t as much dead space around her :)</td>', 'Good shot!  Maybe next time get in a little closer so she takes up more of the picture and there isn''t as much dead space around her :)', '2010-08-01 20:43:24.000000', NULL, 1),
(6112304, 898791, 38930, '<td valign="top">Awesome!  It works perfect for this challenge. Too bad the fly is there, though...</td>', 'Awesome!  It works perfect for this challenge. Too bad the fly is there, though...', '2010-08-01 20:44:00.000000', NULL, 1),
(6112310, 898926, 38930, '<td valign="top">Nice job lighting this.  The focus is a little off, but other than that it''s a great shot!</td>', 'Nice job lighting this.  The focus is a little off, but other than that it''s a great shot!', '2010-08-01 20:45:09.000000', NULL, 1),
